import type { APIRoute } from 'astro';
import { latestManifest } from '../../../../lib/releases';

type DesktopManifest = {
  version: string;
  published_at: string;
  assets: Array<{ os: string; url: string; checksum_sha256: string }>;
};

/**
 * Desktop release lookup backed by the public releases repo's
 * `desktop-latest.json` manifest (generated by obrenna-releases/publish.mjs).
 * Replaces the retired control-plane proxy.
 */
export const GET: APIRoute = async () => {
  try {
    const manifest = await latestManifest<DesktopManifest>('desktop-latest.json');
    if (!manifest || typeof manifest.version !== 'string' || !Array.isArray(manifest.assets)) {
      return Response.json({ version: '', published_at: '', assets: [] }, { status: 404 });
    }
    return Response.json(manifest, {
      headers: { 'Cache-Control': 'public, max-age=300' },
    });
  } catch {
    return Response.json({ version: '', published_at: '', assets: [] }, { status: 503 });
  }
};